breach.segment:
// Ignore nodes that stopped reporting (deleted or replaced) more than 5 minutes before their cluster's newest sample
WHERE last_seen >= cluster_newest - 5 minutes
// Threshold: fraction of total ephemeral storage used, now and in every reported minute of the last 15,
// with at least 12 of the 16 minutes reported, so a new node or sparse data can't fire on a few samples.
// The kubelet starts image garbage collection at 85%; DiskPressure eviction starts at 90%.
| WHERE latest_utilization >= 0.85 AND min_utilization >= 0.85 AND reported_minutes >= 12
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.node_name, latest_utilization, min_utilization, reported_minutes, used_gib, total_gib, last_seen
| SORT latest_utilization DESC
